{"path":"outline.json","content":"{
  "act_one": {
    "description": "新婚夜的重逢：建立军区大房的压抑环境，引入主角和核心冲突——他们必须装作陌生人完成政治联姻，但眼神出卖了彼此。",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "新婚夜",
        "core_event": "军区大院新房，红色喜庆但压抑，窗外有岗哨，电话可能被监听。他们装作陌生人完成政治联姻，但眼神出卖了彼此。新婚夜，他们发现彼此是十年前的青梅竹马。",
        "emotional_tone": "压抑、紧张、震惊",
        "key_scenes": [
          "结婚证（政治文件→旧物→情书，照片NG了十遍才过审）",
          "军装（制服→伪装→裸体下的伤疤）",
          "新婚夜的第一次眼神交流"
        ]
      }
    ],
    "turning_point": "新婚夜，他们发现彼此是十年前的青梅竹马——她以为他死了，他以为她瞎了。"
  },
  "act_two": {
    "description": "压抑的爆发：冲突升级，他们在监听环境下用战场暗语交流，压抑的情感在密闭空间里爆发，每一次触碰都是危险的试探。",
    "key_chapters": [
      {
        "chapter_number": 2,
        "chapter_title": "战场暗语",
        "core_event": "他用战场暗语和她对话，那些手势曾用来杀人现在用来调情。她发现他背上的枪伤是当年为她挡的，但他说是\"训练中受伤\"。",
        "emotional_tone": "压抑、痛苦、深情",
        "key_scenes": [
          "战场暗语的第一次使用",
          "发现枪伤的真相",
          "无声的告白"
        ]
      },
      {
        "chapter_number": 3,
        "chapter_title": "哨兵巡逻时",
        "core_event": "他们在哨兵巡逻时安静做爱，压抑的情感在密闭空间里爆发。每一次触碰都是危险的试探，每一次呻吟都可能被监听。",
        "emotional_tone": "压抑、爆发、危险",
        "key_scenes": [
          "哨兵巡逻的脚步声",
          "安静做爱的压抑",
          "监听环境的威胁"
        ]
      }
    ],
    "turning_point": "他们承认了旧情，但这意味着背叛\"组织安排\"的纯洁性。"
  },
  "act_three": {
    "description": "毁灭或重生：极限二选一，他们面临选择——继续伪装，还是承认旧情？承认旧情就是背叛组织，但压抑旧情就是背叛自己。",
    "key_chapters": [
      {
        "chapter_number": 4,
        "chapter_title": "共犯",
        "core_event": "他们面临极限二选一——继续伪装，还是承认旧情？承认旧情就是背叛组织，但压抑旧情就是背叛自己。他们选择了共犯，在监听下无声告白，用战场暗语说\"我爱你\"。",
        "emotional_tone": "压抑、决绝、深情",
        "key_scenes": [
          "极限二选一的抉择",
          "共犯的默契",
          "战场暗语的\"我爱你\""
        ]
      }
    ],
    "turning_point": "他们选择了共犯，在监听下无声告白，用战场暗语说\"我爱你\"。"
  }
}"}

